create or replace function public.meadow_market_ack_help(p_events jsonb) returns integer language plpgsql security invoker set search_path='' as $$ declare affected integer; begin if auth.uid() is null or jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events)>100 then raise exception 'Invalid help acknowledgment'; end if; update public.meadow_market_visit_events v set outcome=e.value->>'outcome',applied_at=now() from jsonb_array_elements(p_events) e where v.id=(e.value->>'id')::uuid and v.owner_id=auth.uid() and v.outcome='pending' and e.value->>'outcome' in ('applied','not_needed');get diagnostics affected=row_count; return affected; end $$; revoke all on function public.meadow_market_ack_help(jsonb) from public,anon;grant execute on function public.meadow_market_ack_help(jsonb) to authenticated;
